import { courseEnrollmentProof } from './course-enrollment-proof.ts';
import { getAppState } from '@/lib/db';
import { getRazorpayConfig } from '@/lib/integrations';
import { localCourseEnrollmentSettings } from '@/lib/mfw-course-connection';

export async function courseOrderNotes(body: Record<string, unknown>, notes: Record<string, string>, amount: number) {
  // Reserved enrollment notes can only be generated by this server.
  delete notes.mfw_course; delete notes.mfw_course_signature; delete notes.mfw_name; delete notes.mfw_email;
  const workshopId = String(notes.workshopId || '');
  if (!workshopId) return notes;
  const state = await getAppState();
  const link = Object.values(state?.registrationLinks || {}).find(value => value && typeof value === 'object' && String((value as {id?: unknown}).id || '') === workshopId) as { id: string; paid?: boolean; fee?: number; published?: boolean } | undefined;
  const config = await localCourseEnrollmentSettings();
  if (!config?.enabled) return notes;
  const mapping = (config.mappings || []).find((row: {paymentLinkId: string}) => row.paymentLinkId === `registration:${workshopId}`);
  if (!mapping) return notes;
  const expectedAmount = Math.round(Number(link?.fee) * 100);
  if (!link?.paid || link.published === false || !Number.isSafeInteger(expectedAmount) || expectedAmount <= 0 || Math.round(amount * 100) !== expectedAmount) throw new Error('The full course fee is required. Refresh the registration page and try again.');
  const buyer = body.buyer as { mobile?: unknown; name?: unknown; email?: unknown } | undefined;
  const mobile = String(buyer?.mobile || '').replace(/\D/g, '').slice(-10);
  if (!/^[6-9]\d{9}$/.test(mobile)) throw new Error('A valid course buyer mobile number is required.');
  const { webhookSecret } = await getRazorpayConfig();
  if (!webhookSecret) throw new Error('Course payment verification is not configured.');
  return { ...notes, ...courseEnrollmentProof({ workshopId, courseId: mapping.courseId, expectedAmount, requestedAmount: Math.round(amount * 100), mobile, name: String(buyer?.name || 'Course Member'), email: String(buyer?.email || '') }, webhookSecret) };
}
